-- =====================================================================
-- 【v2】开源安全评分看板 · 指标明细展示配置 init（18 指标全量含判定规则 rule 节点）
-- 基于 detail-conf-init.sql（v1）生成，v1 保持不动：
--   conf_json = v1 最终生效 conf（重复 INSERT 取后者，Unique 模型后写覆盖）
--             + classpath security/detail-conf/<code>.json 的 rule 节点（已带 rule 的 4 个指标原样等价）
--   仅涉及 rule（判定规则面板文案，静态透传不求值），其余键与 v1 等值
--   未包含 definition（指标定义节点暂不上线，conf 无此键时前端整块不渲染）
-- 生成：ai-assisted 2026-10-10，已逐项校验（rule 深度等值 + 其余键去 rule 后等值 + rule 文本字符无损）
-- 可重复执行：UNIQUE KEY(metric_code)，Doris Unique 模型后写覆盖先写
--   全新环境：直接执行本文件（含建表）
--   已有环境：直接执行本文件 = 整行覆盖升级（等效于当前线上 + rule 补齐）
-- =====================================================================
-- =====================================================================
-- 开源安全评分看板 · 指标明细展示配置（dm_rd_efc_security_metric_detail_conf）
-- 作用：18 指标的明细页展示配置（summary 数字条 / 失败卡片 / 明细表格列 /
--       文案 / 配色规则）全部存于本表，改文案/列名/颜色规则只需 UPDATE 数据，
--       无需发版。服务端引擎按本表配置渲染，表内缺失时回退 classpath 内置默认。
-- 生成：ai-assisted 2026-09-28，内容依据 docs/0912/明细数据设计freemarker模版/ 21 个原型
-- 可重复执行：UNIQUE KEY(metric_code)，重跑等效覆盖（Doris Unique 模型后写覆盖先写）
--
-- conf_json DSL 速查（引擎实现以此为准）：
--   取值表达式：$path（raw 字段/行字段，查找顺序 行→根上下文）、$this（迭代元素自身）、
--              $s.key（summary 计算值，hidden:true 的项不渲染但可引用）、$p.name（params 常量）、
--              #tpl:文本 {field}（模板，可引用 {s.x}/{p.x}/raw 字段）、
--              #bool:$f:是:否、#ifnull:$f:兜底、#str:$f（对象转字符串）、#ext:$path（取后缀）、
--              #count:$arr、#qcount:$arr:k=v / k!=v（等值/不等过滤计数，多条件逗号分隔）、
--              #sumlen:$arr.sub（嵌套数组长度求和）、#join:$arr:分隔符、#join:$arr:key:分隔符、
--              #joinobj:$obj:分隔符（对象转 k: v 拼接）、
--              #add:$a,$b、#sub:$a,$b、#mul:$a,$b、#pct:$a,$b（百分比取1位）、
--              #sat:$a,$b,$c（布尔真值计数）、
--              #href:https://...（链接模板，引擎统一过 gitcode.com 白名单）
--   level 表达式（配色）：固定值 success/warning/error/critical/na、
--              #map:$f:k1:v1,k2:v2,*:默认、#gt/$a:$b:level 与 #lt:#ge:#eq（比较，操作数可为路径或字面量）、
--              #bool:$f:levelT:levelF（空串=无色）
--   结构约定：summary[{key?,label,value,level?,hidden?}]；
--             failItems 为固定卡数组（卡可带 when:"path op value" 条件，op ∈ = != > >= < <=，
--               操作数 = summary key / raw 字段 / @p.xxx 参数）或 {from,filter{f:v|f:!=v},card{...}}；
--             failNote/failEmptyText/dataNote 为 #tpl 或纯文本；groups 空数组时前端整块不渲染，
--             emptyHint 为占位提示文案（数据未采集场景）。
-- =====================================================================

-- 1. 建表（若已手工建过可跳过）
CREATE TABLE IF NOT EXISTS dm_rd_efc_security_metric_detail_conf (
    metric_code    VARCHAR(64)  NOT NULL COMMENT '指标码，关联 dm_rd_efc_security_metric_conf.metric_code（如 VULNS/MAINTAINED）',
    conf_json      STRING       NOT NULL COMMENT '明细展示配置JSON：summary/failNote/failItems/groups 的mini-DSL（改文案/列名/配色规则只需UPDATE此字段）',
    enabled        TINYINT      NOT NULL DEFAULT 1 COMMENT '1=启用本配置 0=停用（服务自动回退内置默认配置）',
    updated_by     VARCHAR(64)           COMMENT '最近修改人（审计留痕）',
    updated_at     DATETIME              COMMENT '最近修改时间（审计留痕）'
) ENGINE=OLAP
UNIQUE KEY(metric_code)
COMMENT '安全合规评分看板·指标明细展示配置表（手动维护，与 metric_conf 一行一指标对应）'
DISTRIBUTED BY HASH(metric_code) BUCKETS 1;

-- 2. 初始化 18 行配置（按 metric_conf.display_order）

-- 01 LICENSE 开源许可证（阶梯计分·递进累加口径，ladder 数组由服务端按得分推导注入；
--    2026-10-10 递进口径改版，与 detail-conf-patch-license-ladder-progressive.sql 等值）

-- LICENSE
