VALUES ('LICENSE',
'{"summary":[{"key":"spdx","label":"SPDX 标识","value":"#join:$detected_licenses:spdx:、","level":"#gt:$detected_licenses:0:success"},{"key":"reached","hidden":true,"value":"#qcount:$ladder:status=达成"},{"key":"missed","hidden":true,"value":"#qcount:$ladder:status=未达成"},{"label":"当前档位","value":"#tpl:{score} 分","level":"#eq:$score:10:success"},{"label":"已达成台阶","value":"#tpl:{s.reached} / 4"},{"label":"未达成","value":"#tpl:{s.missed}","level":"#gt:$s.missed:0:error"},{"label":"差异对照文件","value":"$license_path","when":"diffCount>0"}],"failNote":"#tpl:递进计分：逐台阶累加（5 → 8 → 9 → 10），无逐条扣分（故卡片不显示扣分值）　｜　当前 {score} 分","failEmptyText":"全部满足：四个台阶全部达成，得 10 分","dataNote":"阶梯计分（递进累加）：有许可证 5 分 → 模板一致 +3 分（8 分）→ copyright 年份与责任人替换正确 +1 分（9 分）→ OSI/FSF 认证 +1 分（10 分）；无许可证 0 分。⚠ 阶梯是递进的：前置台阶未达成时，后续台阶不再判定（显示为未评估）。⚠ 多许可证文件夹仓（如 LICENSES/ 下多个协议文件）：每个文件都参与全部台阶判定，全部达标该台阶才算达成，仓得分取各文件最低分；未达台阶的判定依据会点名具体未达标文件。⚠ 模板不一致时明细自动展示「模板差异对照」：左列为官方模板要求，右列为你的 LICENSE 实际内容，行号为差异内容在你的 LICENSE 文件内的行号；红色行 = 模板有而你的文件缺失的内容，琥珀色行 = 与模板不一致或多出的内容；多许可证文件夹仓以得分最低（瓶颈）文件为对照对象。本指标无 NA 条件，无许可证记 0 分并参与汇聚（0 分进分母，NA 剔除分子分母）。","failItems":{"from":"$ladder","filter":{"status":"!=达成,!=未评估"},"card":{"title":"#tpl:台阶「{name}」{status}","fields":[{"label":"台阶","value":"$name"},{"label":"判定","value":"$status","level":"#map:$status:未达成:error,*:na"},{"label":"判定依据","value":"$why"}],"reason":"#tpl:{why}","searchText":"#tpl:{name} {status} {why}"}},"groups":[{"key":"ladder","label":"计分阶梯","columns":[{"label":"阶梯","key":"step","type":"number"},{"label":"台阶","key":"name","type":"text"},{"label":"是否达成","key":"ok","type":"text"},{"label":"判定依据","key":"why","type":"text"}],"rowsFrom":"$ladder","cellOf":{"step":{"text":"$step"},"name":{"text":"$name"},"ok":{"text":"$status","level":"#map:$status:达成:success,未达成:error,*:na"},"why":{"text":"$why"}},"searchText":"#tpl:{step} {name} {status} {why}"},{"key":"diff","label":"模板差异对照","when":"diffCount>0","columns":[{"label":"行号","key":"line","type":"text"},{"label":"官方模板要求","key":"tpl","type":"wrap"},{"label":"你的 LICENSE 实际内容","key":"file","type":"wrap"}],"rowsFrom":"$diffRows","rowLevel":"#map:$status:del:error,add:warning,mod:warning","cellOf":{"line":{"text":"$line"},"tpl":{"text":"$tpl"},"file":{"text":"$file"}},"searchText":"#tpl:{line} {tpl} {file}"}],"emptyHint":"许可证与官方模板一致（或本批次尚未重新采集），无模板差异对照，仅展示计分阶梯","rule":{"brief":"检查仓库根目录（或 license 目录）下的 LICENSE 文件：是否有许可证、格式是否符合官方模板、版权年份和责任人是否填写正确、是否通过 OSI/FSF 开源认证；多许可证文件夹仓逐文件判定，全部达标才算达标。","formula":"阶梯计分（递进累加）：无许可证 0 → 有许可证 5 → 模板一致 +3（8 分）→ 版权正确 +1（9 分）→ OSI/FSF 认证 +1（10 分）；前置台阶未达成时，后续台阶不再评估；多许可证文件夹仓得分取各文件最低分","conditions":[{"label":"无 LICENSE 文件","value":"0 分（有效低分，不是不参评）"},{"label":"有许可证","value":"5 分（基础分）"},{"label":"格式符合官方模板","value":"+3 分 → 8 分"},{"label":"版权年份和责任人正确","value":"+1 分 → 9 分"},{"label":"通过 OSI/FSF 认证","value":"+1 分 → 10 分"},{"label":"多许可证文件夹（如 LICENSES/ 双协议）","value":"每个文件全台阶判定，全部达标该台阶才达成，仓得分取各文件最低分"},{"label":"模板不一致时","value":"明细自动展示官方模板 vs 你的 LICENSE 的并排差异对照：红色行 = 模板有而文件缺失，琥珀色行 = 内容不一致或多出，行号 = LICENSE 文件内行号"}],"naCondition":"无，本指标恒有得分。","notes":[]}}',
