-- PINNED_DEP
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('PINNED_DEP',
'{"summary":[{"key":"unpinned","hidden":true,"value":"#sub:$total_count,$pinned_count"},{"key":"rate","hidden":true,"value":"#pct:$pinned_count,$total_count"},{"label":"总依赖数","value":"$total_count"},{"label":"已固定","value":"$pinned_count","level":"#eq:$pinned_count:$total_count:success"},{"label":"未固定","value":"#tpl:{s.unpinned}","level":"#gt:$s.unpinned:0:error"},{"label":"合规率","value":"#tpl:{s.rate}%","level":"#lt:$pinned_count:$total_count:warning"}],"failNote":"#tpl:评分：已固定 {pinned_count} / 总依赖数 {total_count} × 10 = {score}　｜　严格口径：镜像须 @sha256 摘要、pip 须 --require-hashes，仅固定版本号不算固定","failEmptyText":"全部满足：全部依赖均已按严格口径固定（镜像 @sha256 / pip --require-hashes 等）","dataNote":"分子分母 = gcheck summary 的 compliant + nonCompliant（无法判定的条目不进分子分母）。判据默认 7 项（ciAction 关闭；downloadThenRun 上游不采集「已固定」的下载条目，命中即存在不合规下载）。依赖明细最多展示前 50 条（truncated=true 时计数仍是全量，判据汇总按明细条目统计）。整改指引为空或 signal 标注口径问题的条目无需整改。","failItems":{"from":"$deps","filter":{"pinned":"=false"},"card":{"title":"#tpl:未固定依赖：{file}","fields":[{"label":"依赖类型","value":"#map:$type:containerImage:容器镜像,downloadThenRun:下载即执行,goCommand:Go 命令,pipCommand:pip 命令,npmCommand:npm 命令,chocoCommand:Chocolatey,nugetCommand:NuGet/.NET,ciAction:Action 引用,unknown:未识别,*:其他"},{"label":"文件","value":"$file"},{"label":"行号","value":"#ifnull:$line:—"},{"label":"依赖引用","value":"#ifnull:$ref:—"},{"label":"信号","value":"#map:$signal:noRef:裸名引用（口径问题）,tagOrBranch:tag/分支引用,abbreviatedSha:缩写 SHA,reusable:可复用 workflow,mutableTag:可变 tag,stageAlias:构建阶段别名（口径问题）,variableRef:变量引用,digestPinned:sha256 摘要,dockerRef:docker 镜像引用,dockerDigestPinned:sha256 摘要,localPath:本地路径,*:—"}],"reason":"#tpl:未满足：{file} 中的依赖未按严格口径固定（{reason}）","searchText":"#tpl:{file} {type} {signal} {ref}"}},"groups":[{"key":"judge","label":"判据汇总","columns":[{"label":"判据","key":"name","type":"text"},{"label":"命中","key":"hit","type":"number"},{"label":"符合","key":"ok","type":"number"},{"label":"不符合","key":"bad","type":"number"},{"label":"合规率","key":"rate","type":"text"}],"rows":[{"name":"容器镜像","hit":"#qcount:$deps:type=containerImage","ok":"#qcount:$deps:type=containerImage,pinned=true","bad":"#qcount:$deps:type=containerImage,pinned=false"},{"name":"下载即执行","hit":"#qcount:$deps:type=downloadThenRun","ok":"#qcount:$deps:type=downloadThenRun,pinned=true","bad":"#qcount:$deps:type=downloadThenRun,pinned=false"},{"name":"Go 命令","hit":"#qcount:$deps:type=goCommand","ok":"#qcount:$deps:type=goCommand,pinned=true","bad":"#qcount:$deps:type=goCommand,pinned=false"},{"name":"pip 命令","hit":"#qcount:$deps:type=pipCommand","ok":"#qcount:$deps:type=pipCommand,pinned=true","bad":"#qcount:$deps:type=pipCommand,pinned=false"},{"name":"npm 命令","hit":"#qcount:$deps:type=npmCommand","ok":"#qcount:$deps:type=npmCommand,pinned=true","bad":"#qcount:$deps:type=npmCommand,pinned=false"},{"name":"Chocolatey","hit":"#qcount:$deps:type=chocoCommand","ok":"#qcount:$deps:type=chocoCommand,pinned=true","bad":"#qcount:$deps:type=chocoCommand,pinned=false"},{"name":"NuGet / .NET","hit":"#qcount:$deps:type=nugetCommand","ok":"#qcount:$deps:type=nugetCommand,pinned=true","bad":"#qcount:$deps:type=nugetCommand,pinned=false"}],"cellOf":{"name":{"text":"$name"},"hit":{"text":"$hit"},"ok":{"text":"$ok","level":"#gt:$ok:0:success"},"bad":{"text":"$bad","level":"#gt:$bad:0:error"},"rate":{"text":"#pct:$ok,$hit"}},"searchText":"#tpl:{name} {hit} {ok} {bad}"},{"key":"deps","label":"依赖明细","columns":[{"label":"依赖类型","key":"type","type":"text"},{"label":"位置","key":"file","type":"text"},{"label":"行号","key":"line","type":"text"},{"label":"依赖引用","key":"ref","type":"text"},{"label":"判定","key":"pin","type":"text"},{"label":"信号","key":"signal","type":"text"},{"label":"判定依据 / 整改指引","key":"fix","type":"text"}],"rowsFrom":"$deps","cellOf":{"type":{"text":"#map:$type:containerImage:容器镜像,downloadThenRun:下载即执行,goCommand:Go 命令,pipCommand:pip 命令,npmCommand:npm 命令,chocoCommand:Chocolatey,nugetCommand:NuGet/.NET,ciAction:Action 引用,unknown:未识别,*:其他"},"file":{"text":"$file"},"line":{"text":"#ifnull:$line:—"},"ref":{"text":"#ifnull:$ref:—"},"pin":{"text":"#bool:$pinned:已固定:未固定","level":"#bool:$pinned:success:error"},"signal":{"text":"#map:$signal:noRef:裸名引用（口径问题）,tagOrBranch:tag/分支引用,abbreviatedSha:缩写 SHA,reusable:可复用 workflow,mutableTag:可变 tag,stageAlias:构建阶段别名（口径问题）,variableRef:变量引用,digestPinned:sha256 摘要,dockerRef:docker 镜像引用,dockerDigestPinned:sha256 摘要,localPath:本地路径,*:—"},"fix":{"text":"#ifnull:$reason:—"}},"searchText":"#tpl:{file} {type} {signal} {ref}"}],"emptyHint":"本仓库未识别到任何依赖（NA），或 gcheck 无法运行，无明细数据","rule":{"brief":"检查 CI/CD 与构建文件中的依赖是否固定到不可变版本（gcheck 严格口径，对齐 OSSF Scorecard v5.5.0 pinned-dependencies）：容器镜像须以 @sha256 摘要引用、pip 安装须 --require-hashes、npm 须 npm ci 或固定哈希、go install / go get 须固定版本、下载即执行须按哈希固定。workflow action 引用默认不检测。","formula":"得分 = 已固定依赖数 / 依赖总数 × 10","conditions":[{"label":"已固定","value":"镜像 @sha256 摘要 / pip --require-hashes / npm ci / go 固定版本 / 下载固定到 40 位提交 SHA"},{"label":"未固定","value":"浮动 tag（如 latest）、仅版本号无哈希、可变分支引用"},{"label":"口径问题条目","value":"signal 标注 noRef / stageAlias / variableRef / localPath 等的条目没有可通过的整改路径，属口径问题，不开整改单"}],"naCondition":"未识别到任何依赖（not-applicable）、无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA，不计分子分母。","notes":["2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）","workflow action 引用默认不检测（GitCode 平台不进行 actions 版本依赖扫描，官方插件裸名引用没有可固定的版本位）"]}}',
1, 'ai-assisted', NOW());

-- BINARY_ARTIFACTS
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('BINARY_ARTIFACTS',
'{"params":{"unit":"1"},"summary":[{"key":"n","label":"二进制文件数","value":"$binary_count","level":"#gt:$binary_count:0:error"},{"label":"每个扣分","value":"#tpl:{p.unit}"},{"key":"total","hidden":true,"value":"#mul:$binary_count,$p.unit"},{"label":"合计扣分","value":"#tpl:-{s.total}","level":"#gt:$binary_count:0:error"},{"label":"得分公式","value":"max(0, 10 − n)"}],"failNote":"#tpl:评分：max(0, 10 − 二进制文件数 {binary_count}) = {score}　｜　逐文件累加扣分（每个 {p.unit} 分）","failEmptyText":"全部满足：按文件内容魔数识别，全仓未检出二进制可执行产物，无扣分","dataNote":"扫描全仓文件树，按文件内容魔数识别真二进制可执行产物：ELF（Linux 可执行 / 共享库）、PE（Windows exe / dll）、Mach-O（macOS 可执行）、WASM（WebAssembly 模块）、ar 归档（.a 静态库）。文件名后缀不再作为判定依据：.gz / .zip / .pdf / .jar / .pyc 等非可执行产物不上报。自动排除 .git、testdata 等目录；vendor / node_modules 目录照报（上游口径）。本指标没有 NA 条件。","failItems":{"from":"$artifact_types","card":{"title":"#tpl:检出二进制文件：{path}","fields":[{"label":"文件路径","value":"$path"},{"label":"产物类型","value":"#map:$signal:elf:ELF 可执行/共享库,pe:PE 可执行,macho:Mach-O 可执行,macho-fat-or-java-class:Mach-O fat/Java class,wasm:WASM 模块,archive:ar 归档,*:其他二进制"},{"label":"扣分","value":"#tpl:-{p.unit}","level":"error"}],"reason":"#tpl:未满足：文件 {path} 内容命中二进制魔数特征（{signal}）","searchText":"$path"}},"groups":[{"key":"bin","label":"二进制文件清单","columns":[{"label":"文件路径","key":"path","type":"text"},{"label":"产物类型","key":"type","type":"text"},{"label":"扣分","key":"ded","type":"number"}],"rowsFrom":"$artifact_types","cellOf":{"path":{"text":"$path"},"type":{"text":"#map:$signal:elf:ELF 可执行/共享库,pe:PE 可执行,macho:Mach-O 可执行,macho-fat-or-java-class:Mach-O fat/Java class,wasm:WASM 模块,archive:ar 归档,*:其他二进制"},"ded":{"text":"#tpl:-{p.unit}","level":"error"}},"searchText":"$path"}],"rule":{"brief":"检查仓库中是否直接提交了二进制可执行产物（gcheck 严格口径：按文件内容魔数识别，不再按文件名后缀判定）。识别 ELF / PE / Mach-O / WASM 可执行与 ar 归档等真二进制。","formula":"得分 = 10 − 二进制文件数（最低 0 分，每个文件扣 1 分）","conditions":[{"label":"命中即扣分","value":"文件内容命中魔数特征（ELF / PE / Mach-O / WASM / ar 归档），不区分目录"}],"naCondition":"无，本指标恒有得分。","notes":["2026-10-09 口径切换：由文件名后缀清单改为文件内容魔数识别（gcheck binary-artifacts），历史批次数据不可比",".gz / .zip / .pdf / .jar / .pyc 等非可执行产物不再上报","vendor / node_modules 目录照报（上游口径）"]}}',
1, 'ai-assisted', NOW());

-- BRANCH_PROTECTION
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('BRANCH_PROTECTION',
'{"summary":[{"key":"base","label":"平台默认管控基线","value":"#map:$base_pass:1:达标,0:未达标,*:—","level":"#map:$base_pass:1:success,0:error,*:"},{"key":"yaml","label":"rebot.yaml 增强管控","value":"#map:$has_rebot_yaml:1:已配置,0:未配置,*:—"},{"key":"need","label":"lgtm 审批要求","value":"#ifnull:$lgtm_need_num:—"},{"key":"prpass","label":"PR lgtm 达标","value":"#map:$pr_lgtm_pass:1:全部达标,0:存在未达标,*:—","level":"#map:$pr_lgtm_pass:1:success,0:error,*:"}],"failNote":"#tpl:评分规则：① 未配置 rebot.yaml → 按平台默认管控计 8 分；② 已配置且近 30 个已合入 PR 每个均有要求人数的不同人 /lgtm → 10 分；③ 已配置但存在未达标 PR → 8 分。当前得分 {score} 分","failEmptyText":"满分：已配置 rebot.yaml，且窗口内每个 PR 均满足不同人 lgtm 审批要求","dataNote":"数据来源：P1 扫描 .infra_self_service/rebot.yaml 配置 + 近 30 个已合入 PR 的 /lgtm 评论。基线 8 分 = 平台默认分支保护生效；满分需配置 rebot.yaml（lgtm_need_num=2）且每个 PR 有 2 个不同人的 /lgtm。","emptyHint":"该仓库暂无分支保护扫描数据","failItems":[{"when":"has_rebot_yaml=0","title":"增强管控未启用","fields":[{"label":"rebot.yaml","value":"未配置"},{"label":"平台默认管控","value":"生效（基线 8 分）","level":"success"},{"label":"增强建议","value":"配置 .infra_self_service/rebot.yaml 并设置 lgtm_need_num=2"}],"reason":"基线达标：仓库内未检出 .infra_self_service/rebot.yaml，按平台默认管控计 8 分；配置增强管控并满足双人 lgtm 可得满分","searchText":"rebot.yaml 未配置 增强管控"},{"when":"pr_lgtm_pass=0","title":"存在 lgtm 审批未达标 PR","fields":[{"label":"rebot.yaml","value":"已配置"},{"label":"PR lgtm 达标","value":"存在未达标","level":"error"}],"reason":"已配置 rebot.yaml 增强管控，但近 30 个已合入 PR 中存在未满足不同人 /lgtm 要求的 PR，按 8 分计","searchText":"lgtm 未达标"}],"groups":[{"key":"prs","label":"近 30 PR lgtm 审批明细","columns":[{"label":"PR 号","key":"num","type":"number"},{"label":"lgtm 数","key":"cnt","type":"number"},{"label":"评审人数","key":"distinct","type":"number"},{"label":"是否达标","key":"pass","type":"text"},{"label":"审批人","key":"authors","type":"text"}],"rowsFrom":"$pr_lgtm_detail","cellOf":{"num":{"text":"#tpl:#{pr_number}","href":"#href:https://gitcode.com/{repoPath}/merge_requests/{pr_number}"},"cnt":{"text":"$lgtm_count"},"distinct":{"text":"$distinct_author"},"pass":{"text":"#bool:$pass:达标:未达标","level":"#bool:$pass:success:error"},"authors":{"text":"#join:$lgtms:login:、"}},"searchText":"#tpl:{pr_number} {lgtm_count}"}],"rule":{"brief":"GitCode 平台已默认提供基础分支保护（分支锁定、强制走 PR、评审门槛），本指标主要考察进阶要求：是否通过 .infra_self_service/rebot.yaml 配置了双人 LGTM（lgtm_need_num=2）并真正落实。","formula":"二元计分：默认 8 分；配置 lgtm_need_num=2 且近 30 个已合入 PR 每个都有两条不同人的 /lgtm = 10 分；配置了但未通过仍 8 分（无中间分）","conditions":[{"label":"基础 8 分","value":"平台默认分支保护，恒定满足"},{"label":"满分 10 分","value":"rebot.yaml 配置 lgtm_need_num=2，且近 30 PR 每个都有两条来自不同人（剔除机器人和 PR 作者）的 /lgtm"}],"naCondition":"无，本指标恒有得分。","notes":["lgtm_need_num 取其他值（1/3/…）不触发双人检查，按默认 8 分"]}}',
1, 'ai-assisted', NOW());

-- WEBHOOKS
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('WEBHOOKS',
'{"summary":[{"key":"all","label":"Webhook 总数","value":"#count:$webhooks"},{"key":"act","hidden":true,"value":"#ifnull:$active_count:0"},{"key":"secured","label":"活跃中已配密钥","value":"#ifnull:$secured_count:0","level":"#gt:$s.secured:0:success"},{"key":"unsecured","label":"活跃中未配密钥","value":"#sub:$active_count,$secured_count","level":"#gt:$s.unsecured:0:error"},{"label":"未激活（不计入）","value":"#sub:#count:$webhooks,$active_count","level":"na"}],"failNote":"#tpl:评分：⌊10 × 已配置密钥 {secured_count} / 活跃钩子 {active_count}⌋ = {score}　｜　每条未配置密钥的活跃钩子扣分　｜　⌊ ⌋ 为向下取整","failEmptyText":"全部满足：活跃 Webhook 均已配置密钥","dataNote":"分母只计 active=1 的活跃钩子；未激活与状态未知的钩子均不计入分母。已配置密钥判定 = active=1 且 password_is_null=0。采集层不落密码明文，只落 password_is_null 布尔位。Webhook 创建时间暂未采集，明细列已降级。","failItems":{"from":"$webhooks","filter":{"active":"=1","password_is_null":"=1"},"card":{"title":"#tpl:Webhook #{id} 未配置密钥","fields":[{"label":"#","value":"#tpl:{id}"},{"label":"URL","value":"$url"},{"label":"活跃状态","value":"活跃"},{"label":"密钥配置","value":"未配置","level":"error"}],"reason":"#tpl:未满足：活跃 Webhook #{id}（{url}）未配置密钥","searchText":"#tpl:{id} {url}"}},"groups":[{"key":"wh","label":"Webhook 清单","columns":[{"label":"id","key":"id","type":"number"},{"label":"Webhook URL","key":"url","type":"text"},{"label":"活跃状态","key":"active","type":"text"},{"label":"密钥配置","key":"secret","type":"text"}],"rowsFrom":"$webhooks","cellOf":{"id":{"text":"#tpl:{id}"},"url":{"text":"$url"},"active":{"text":"#bool:$active:活跃:未激活","level":"#bool:$active::na"},"secret":{"text":"#bool:$password_is_null:未配置:已配置","level":"#bool:$password_is_null:error:success"}},"searchText":"#tpl:{id} {url}"}],"rule":{"brief":"检查仓库活跃的 Webhook 中，有多少配置了密钥（secret）。未配密钥的 Webhook 请求可被伪造。","formula":"得分 = 10 × 配置密钥的 Webhook 数 / 活跃 Webhook 总数（向下取整）","conditions":[{"label":"已配密钥","value":"活跃（active）且密钥非空"},{"label":"无活跃钩子","value":"10 分（没有入口即没有风险，不是不参评）"},{"label":"全部未配","value":"0 分"}],"naCondition":"无，本指标恒有得分。","notes":[]}}',
1, 'ai-assisted', NOW());

-- CI_TESTS
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('CI_TESTS',
'{"summary":[{"key":"total","label":"纳入统计 PR","value":"$pr_total_count"},{"key":"ci","label":"已跑 CI","value":"#qcount:$pr_ci_detail:has_ci=1","level":"#gt:$s.ci:0:success"},{"key":"noci","label":"未跑 CI","value":"#qcount:$pr_ci_detail:has_ci=0","level":"#gt:$s.noci:0:error"},{"key":"rate","hidden":true,"value":"#pct:$s.ci,$pr_total_count"},{"key":"deduct","hidden":true,"value":"#sub:10,$score"}],"failNote":"#tpl:评分：已跑 CI {s.ci} / 纳入统计 {pr_total_count} × 10 = {score}　｜　每条未跑 CI 的 PR 扣 10 / {pr_total_count}，合计扣 {s.deduct}　｜　CI 覆盖率 {s.rate}%","failEmptyText":"全部满足：近 30 次已合入 PR 均匹配到流水线执行记录，无扣分","dataNote":"统计近 30 次已合入 PR 的 CI 执行记录。流水线链接明细暂未采集。","failItems":{"from":"$pr_ci_detail","filter":{"has_ci":"=0"},"card":{"title":"#tpl:PR #{number} 未跑 CI","fields":[{"label":"PR","value":"#tpl:#{number}","href":"$url"},{"label":"标题","value":"#ifnull:$title:—"},{"label":"创建人","value":"#ifnull:$creator:—"},{"label":"CI 状态","value":"未跑 CI","level":"error"}],"reason":"#tpl:未满足：PR #{number} 已合入但未匹配到流水线执行记录","searchText":"#tpl:{number} {title} {creator} 未跑 CI"}},"groups":[{"key":"pr","label":"PR CI 明细","columns":[{"label":"PR","key":"num","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"},{"label":"CI 状态","key":"ci","type":"text"}],"rowsFrom":"$pr_ci_detail","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"title":{"text":"#ifnull:$title:—"},"creator":{"text":"#ifnull:$creator:—"},"ci":{"text":"#bool:$has_ci:已跑 CI:未跑 CI","level":"#bool:$has_ci:success:error"}},"searchText":"#tpl:{number} {title} {creator}"}],"rule":{"brief":"检查最近 30 次已合入 PR（与代码评审同口径）中，每个 PR 是否有 CI 流水线执行记录——只要触发过流水线即视为有 CI。","formula":"得分 = 10 × 有 CI 的 PR 数 / PR 总数","conditions":[{"label":"有 CI","value":"PR 关联到流水线执行记录（CodeArts 关联表）"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"仓库无已合入 PR 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]}}',
1, 'ai-assisted', NOW());

-- SIGNED_RELEASES（2026-10-20 口径：sha256+签名 AND，移除 SLSA）
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('SIGNED_RELEASES',
'{"summary":[{"label":"评估版本数","value":"$release_count"},{"label":"签名齐全","value":"$signed_count","level":"#gt:$signed_count:0:success"},{"key":"unsigned","label":"不满足版本数","value":"#sub:$release_count,$signed_count","level":"#gt:$s.unsigned:0:error"},{"label":"其中仅源码包","value":"#qcount:$releases:source_only=1"}],"failNote":"#tpl:评分：全部版本须同时含 sha256 校验文件与数字签名文件才得 10 分，本仓库有 {s.unsigned} 个版本不满足　→　score = {score}（二元判定，非按比例扣分；故卡片不显示逐条扣分）","failEmptyText":"全部满足：最近 30 个版本均同时含 sha256 校验文件与数字签名文件","dataNote":"评估范围为最近 30 个版本（含预发布，2026-10-10 调整）；仅有源码包（source only）的版本按上游口径忽略。满足判定 = 附件同时包含 sha256 校验文件（.sha256/.sha256sum）与数字签名资产（.asc/.sig/.pgp 等），两者缺一即不满足。2026-10-20 口径调整：sha256 与签名须同时存在（AND），移除 SLSA Provenance 等效判定。","failItems":{"from":"$releases","filter":{"signed":"=0"},"card":{"title":"#tpl:版本 {tag} 不满足签名要求","fields":[{"label":"版本","value":"$tag"},{"label":"sha256 校验","value":"#bool:$has_sha256:已提供:未提供","level":"#bool:$has_sha256:success:error"},{"label":"数字签名","value":"#bool:$has_signature:已提供:未提供","level":"#bool:$has_signature:success:error"},{"label":"仅源码包","value":"#bool:$source_only:是:否"}],"reason":"#tpl:未满足：版本 {tag} 未同时检出 sha256 校验文件与数字签名资产","searchText":"$tag"}},"groups":[{"key":"rel","label":"版本清单","columns":[{"label":"版本","key":"tag","type":"text"},{"label":"签名齐全","key":"signed","type":"text"},{"label":"sha256 校验","key":"sha256","type":"text"},{"label":"数字签名","key":"sig","type":"text"},{"label":"仅源码包","key":"so","type":"text"}],"rowsFrom":"$releases","cellOf":{"tag":{"text":"$tag"},"signed":{"text":"#bool:$signed:满足:不满足","level":"#bool:$signed:success:error"},"sha256":{"text":"#bool:$has_sha256:是:否","level":"#bool:$has_sha256:success:error"},"sig":{"text":"#bool:$has_signature:是:否","level":"#bool:$has_signature:success:error"},"so":{"text":"#bool:$source_only:是:否"}},"searchText":"$tag"}],"rule":{"brief":"检查最近 30 个 Release 版本（含预发布，忽略纯源码包版本）的附件中，是否同时包含 sha256 校验文件和数字签名文件。","formula":"全部版本均同时含 sha256 校验文件与签名文件 = 10 分；任一版本缺少任一项 = 0 分（一票否决）","conditions":[{"label":"sha256 校验文件","value":".sha256 / .sha256sum"},{"label":"数字签名资产","value":".asc / .sig / .pgp / .gpg / .minisig / .pem / .crt / .cer / .p7s"}],"naCondition":"仓库没有任何 Release 时，本指标不参评（不计入总分，不是 0 分）。","notes":["2026-10-20 口径调整：sha256 与签名须同时存在（AND），移除 SLSA Provenance 等效判定"]}}',
1, 'ai-assisted', NOW());

-- PACKAGING
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('PACKAGING',
'{"summary":[{"label":"制品上传插件","value":"#bool:$has_publish_plugin:检测到:未检测到","level":"#bool:$has_publish_plugin:success:error"},{"label":"openEuler 构建命中","value":"#bool:$in_openeuler_project:是:否","level":"#bool:$in_openeuler_project:success:na"},{"label":"workflow 数","value":"#count:$workflow_paths"}],"failNote":"#tpl:评分：检测到自动发包流程（制品上传插件或 openEuler 包清单命中）= 10 分，未检测到 = 0 分 → score = {score}","failEmptyText":"全部满足：已检测到制品上传插件或 openEuler 构建命中，计 10 分","dataNote":"当前检查项：核心检查 workflow 中是否存在制品上传插件，检查插件为 obs-upload、upload-artifact 两种。注：openEuler 社区存在独立发包流程，仓库名命中 openEuler 包清单同样视为满足。","failItems":[{"when":"has_publish_plugin=0","title":"未检测到自动发包流程","fields":[{"label":"检查项","value":"workflow 制品上传插件"},{"label":"检查插件","value":"obs-upload、upload-artifact"},{"label":"检查结果","value":"未检出","level":"error"},{"label":"openEuler 独立发包","value":"#bool:$in_openeuler_project:命中:未命中","level":"#bool:$in_openeuler_project:success:error"}],"reason":"未满足：workflow 中未检出制品上传插件（obs-upload / upload-artifact），且未命中 openEuler 包清单，视为未建立自动发包流程","searchText":"未检测到自动发包流程 packaging"}],"groups":[{"key":"chk","label":"当前检查项","columns":[{"label":"检查项","key":"item","type":"text"},{"label":"检查范围","key":"scope","type":"text"},{"label":"判定条件","key":"rule","type":"text"}],"rows":[{"item":"制品上传插件","scope":".gitcode/workflows 目录","rule":"workflow 中 uses 值为 obs-upload 或 upload-artifact"},{"item":"openEuler 独立发包","scope":"openEuler 包清单","rule":"仓库名命中 openEuler 包名（openEuler 社区存在独立发包流程）"}],"cellOf":{"item":{"text":"$item"},"scope":{"text":"$scope"},"rule":{"text":"$rule"}},"searchText":"#tpl:{item} {scope}"},{"key":"pk","label":"插件命中明细","columns":[{"label":"workflow 文件","key":"wf","type":"text"},{"label":"命中插件","key":"uses","type":"text"}],"rowsFrom":"$publish_plugins","cellOf":{"wf":{"text":"$workflow"},"uses":{"text":"$uses","level":"success"}},"searchText":"$workflow"}],"emptyHint":"未检出制品上传插件且未命中 openEuler 包清单时，无插件命中明细","rule":{"brief":"检查仓库是否具备自动化发包能力，满足任一即算：workflow 中配置了制品上传插件（obs-upload 或 upload-artifact）；或仓库被收录在 openEuler（Eluermaker）打包工程清单中。","formula":"具备自动化发包能力 = 10 分；未检出 = 0 分（视为未建立自动发包流程）","conditions":[{"label":"条件 1","value":"workflow 中使用制品上传插件（obs-upload / upload-artifact）"},{"label":"条件 2","value":"仓库命中 openEuler 打包工程清单（包名口径比对）"}],"naCondition":"无，本指标恒有得分。","notes":[]}}',
1, 'ai-assisted', NOW());

-- FUZZING
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('FUZZING',
'{"summary":[{"key":"hitN","hidden":true,"value":"#count:$hit_criteria"},{"label":"当前档位","value":"#map:$tier:oss_fuzz:OSS-Fuzz（10分）,clusterfuzzlite:ClusterFuzzLite（10分）,native_fuzz:原生 fuzz（5分）,property_testing:属性测试（3分）,none:无任何 Fuzzing 活动（0分）","level":"#map:$tier:oss_fuzz:success,clusterfuzzlite:success,native_fuzz:success,property_testing:warning,none:error"},{"label":"命中判据","value":"#tpl:{s.hitN} / 17"},{"label":"OSS-Fuzz","value":"#bool:$in_ossfuzz:已收录:未收录","level":"#bool:$in_ossfuzz:success:"},{"label":"ClusterFuzzLite","value":"#bool:$has_clusterfuzzlite:已配置:未配置"},{"label":"原生 fuzz","value":"#bool:$native_fuzz:检出:未检出"}],"failNote":"#tpl:阶梯计分：只取满足的最高档，无逐条扣分（故卡片不显示扣分值）　｜　当前 {score} 分","failEmptyText":"满分：已集成 OSS-Fuzz 或配置 ClusterFuzzLite，取最高档 10 分","dataNote":"OSS-Fuzz 判定依据 OSS-Fuzz 官方项目名单快照（main_repo 归一化比对）。原生 fuzz / property-testing 按代码特征识别（fuzz 函数 / 构建脚本 / 测试框架）。证据明细最多展示前 50 条。17 项判据全部未命中时产出仓库级未检出条目（无文件可派单），不单独铺卡。","failItems":[{"when":"tier=none","title":"未检出任何模糊测试活动","fields":[{"label":"当前档位","value":"无任何 Fuzzing 活动（0 分）","level":"error"},{"label":"OSS-Fuzz 名单","value":"#bool:$in_ossfuzz:已收录:未收录"},{"label":"ClusterFuzzLite","value":"未配置"},{"label":"原生 fuzz","value":"未检出"},{"label":"属性测试","value":"未检出"}],"reason":"未满足：17 项判据全部未命中 —— 未检出 OSS-Fuzz 收录 / ClusterFuzzLite 配置 / 语言原生 fuzz / property-testing 任何一类模糊测试活动","searchText":"fuzzing 未检出 模糊测试"}],"groups":[{"key":"ladder","label":"阶梯判定","columns":[{"label":"台阶","key":"name","type":"text"},{"label":"档位分","key":"score","type":"number"},{"label":"是否计入","key":"used","type":"text"},{"label":"判定依据","key":"check","type":"text"}],"rows":[{"name":"集成 OSS-Fuzz","score":"10","used":"#map:$tier:oss_fuzz:计入（当前档位）,*:未计入","check":"仓库身份与 OSS-Fuzz 名单每个项目的 main_repo 归一化成小写 host/org/repo 后比对"},{"name":"配置 ClusterFuzzLite","score":"10","used":"#map:$tier:clusterfuzzlite:计入（当前档位）,*:未计入","check":"检出精确路径 .clusterfuzzlite/Dockerfile（大小写敏感精确比对），且文件内容存在非空、非 # 注释的有效行"},{"name":"原生 fuzz","score":"5","used":"#map:$tier:native_fuzz:计入（当前档位）,*:未计入","check":"7 项引擎型判据命中任一：Go testing.F / LibFuzzer（C·C++·Swift）/ Atheris / cargo-fuzz / Jazzer"},{"name":"属性测试","score":"3","used":"#map:$tier:property_testing:计入（当前档位）,*:未计入","check":"8 项属性测试判据命中任一：Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam"},{"name":"无任何 Fuzzing 活动","score":"0","used":"#map:$tier:none:计入（当前档位）,*:未计入","check":"17 项判据全部未命中 —— 仓库级未检出条目（id=null、scope=repo）"}],"cellOf":{"name":{"text":"$name"},"score":{"text":"$score"},"used":{"text":"$used"},"check":{"text":"$check"}},"searchText":"#tpl:{name} {score} {check}"},{"key":"sig","label":"fuzz 集成证据","columns":[{"label":"判据","key":"crit","type":"text"},{"label":"文件","key":"file","type":"text"},{"label":"行号","key":"line","type":"text"},{"label":"代码片段","key":"snippet","type":"text"}],"rowsFrom":"$signals","cellOf":{"crit":{"text":"#map:$criterion:ossFuzz:OSS-Fuzz,clusterFuzzLite:ClusterFuzzLite,go-native:go test fuzz,c-libfuzzer:C libFuzzer,cpp-libfuzzer:C++ libFuzzer,swift-libfuzzer:Swift libFuzzer,python-atheris:Python atheris,rust-cargo-fuzz:Rust cargo-fuzz,java-jazzer:Java Jazzer,haskell-property-testing:Haskell 属性测试,javascript-property-testing:JavaScript 属性测试,typescript-property-testing:TypeScript 属性测试,csharp-property-testing:C# 属性测试,fsharp-property-testing:F# 属性测试,erlang-property-testing:Erlang 属性测试,elixir-property-testing:Elixir 属性测试,gleam-property-testing:Gleam 属性测试,*:其他"},"file":{"text":"$file"},"line":{"text":"#ifnull:$line:—"},"snippet":{"text":"#ifnull:$snippet:—"}},"searchText":"#tpl:{criterion} {file} {snippet}"}],"emptyHint":"未检出模糊测试活动（0 分）时无证据明细；NA 仓库（gcheck 无法运行）同样无明细数据","rule":{"brief":"检查仓库是否开展模糊测试活动：收录于 OSS-Fuzz 官方项目名单、通过 .clusterfuzzlite/Dockerfile 集成 ClusterFuzzLite、使用语言原生 fuzz 能力（go test fuzz / libFuzzer / atheris / cargo-fuzz / Jazzer 等），或配置 property-testing。共 17 项判据（2 项非语言 + 7 项引擎型 + 8 项属性测试），检测到的工具数量不影响评分。","formula":"阶梯计分，只取满足的最高档：OSS-Fuzz 或 ClusterFuzzLite = 10 分；语言原生 fuzz = 5 分；property-testing = 3 分；全部未检出 = 0 分。各档相互独立，不存在低档阻断。","conditions":[{"label":"OSS-Fuzz","value":"仓库收录于 OSS-Fuzz 官方项目名单（main_repo 归一化比对）"},{"label":"ClusterFuzzLite","value":"检出精确路径 .clusterfuzzlite/Dockerfile（大小写敏感精确比对），且文件内容存在非空、非 # 注释的有效行"},{"label":"原生 fuzz","value":"go test fuzz、C/C++/Swift libFuzzer、python-atheris、rust cargo-fuzz、java Jazzer"},{"label":"property-testing","value":"Haskell / JS / TS / C# / F# / Erlang / Elixir / Gleam 属性测试框架"}],"naCondition":"无默认分支 / checkout 失败 / gcheck 超时等无法运行时为 NA。「全部未检出」是有效 0 分，不是 NA。","notes":["口径 = OSSF Scorecard v5.5.0 fuzzing check + property-testing=3 分阶梯扩展（Q-048 答复：8 项属性测试判据都算分）","2026-10-09 起生产数据来自 security_gcheck_scan.py（gcheck 离线扫描批次）"]}}',
1, 'ai-assisted', NOW());

-- SAST
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('SAST',
'{"summary":[{"key":"hooks","hidden":true,"value":"#count:$hooks"},{"label":"检测结果","value":"#bool:$has_precommit:检出:未检出","level":"#bool:$has_precommit:success:error"},{"label":"检测文件","value":"#ifnull:$precommit_path:—"},{"label":"hooks 数","value":"#ifnull:$s.hooks:—"}],"failNote":"#tpl:评分：二元判定（检出 pre-commit 配置文件即 10 分，未检出即 0 分）→ score = {score}","failEmptyText":"#tpl:全部满足：已检出 pre-commit 配置文件并配置了 {s.hooks} 个 hook","dataNote":"二元判定：检出 pre-commit 配置文件即 10 分，未检出即 0 分。本指标没有 NA 条件。hooks 元素结构以实际采集数据为准。","failItems":[{"when":"has_precommit=0","title":"未检出 pre-commit 配置文件","fields":[{"label":"检测路径","value":".pre-commit-config.yaml / .yml"},{"label":"检出结果","value":"均未检出","level":"error"},{"label":"判定","value":"未集成 pre-commit","level":"error"}],"reason":"未满足：仓库内未检出 pre-commit 配置文件，视为未集成 SAST","searchText":"pre-commit 未检出 sast"}],"groups":[{"key":"detect","label":"检测项","columns":[{"label":"检测项","key":"item","type":"text"},{"label":"路径","key":"path","type":"text"},{"label":"结果","key":"result","type":"text"}],"rows":[{"item":"仓库根目录 .pre-commit-config.yaml","path":".pre-commit-config.yaml"},{"item":"仓库根目录 .pre-commit-config.yml","path":".pre-commit-config.yml"}],"cellOf":{"item":{"text":"$item"},"path":{"text":"$path"},"result":{"text":"#bool:$has_precommit:检出:未检出","level":"#bool:$has_precommit:success:error"}},"searchText":"#tpl:{item} {path}"},{"key":"hook","label":"hooks 清单","columns":[{"label":"hook","key":"id","type":"text"},{"label":"说明","key":"desc","type":"text"}],"rowsFrom":"$hooks","cellOf":{"id":{"text":"#str:$this"},"desc":{"text":"—"}},"searchText":"#str:$this"}],"rule":{"brief":"检查 pre-commit 配置（根目录或 pre-commit/ 目录，两处同时存在则合并）或 workflow 文件中，是否使用了任一静态分析（SAST）工具，不区分语言。","formula":"命中任一工具 = 10 分（多个不加分）；有配置文件但 0 命中 = 0 分","conditions":[{"label":"工具清单","value":"clang-tidy / bandit / eslint / gosec / clippy / spotbugs / gitleaks / luacheck"}],"naCondition":"既没有 pre-commit 配置文件、又没有 workflow 文件时，本指标不参评（不计入总分，不是 0 分）。","notes":[]}}',
1, 'ai-assisted', NOW());

-- SECURITY_POLICY
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('SECURITY_POLICY',
'{"params":{"s1":"1","s6":"6","s3":"3"},"summary":[{"label":"漏洞披露信息","value":"#bool:$disclosure:满足:未满足","level":"#bool:$disclosure:success:error"},{"label":"联系链接","value":"#bool:$link:满足:未满足","level":"#bool:$link:success:error"},{"label":"自由文本说明","value":"#bool:$free_text:满足:未满足","level":"#bool:$free_text:success:error"},{"key":"sat","hidden":true,"value":"#sat:$disclosure,$link,$free_text"},{"label":"已满足","value":"#tpl:{s.sat} / 3","level":"#lt:$s.sat:3:error"}],"failNote":"#tpl:评分：三项独立加分 —— 漏洞披露信息 +1、联系链接 +6、自由文本说明 +3 → score = {score}。本指标既不是档位判定，也不是按比例扣分","failEmptyText":"全部满足：仓库内已检出 SECURITY.md，三项检测（漏洞披露信息 / 联系链接 / 自由文本说明）全部满足","dataNote":"三项独立加分：漏洞披露信息 +1、联系链接 +6、自由文本说明 +3。无 SECURITY.md 时按口径记 0 分并参与汇聚（进分母），不是 NA。SECURITY.md 检出路径明细暂未采集。","failItems":[{"when":"disclosure=0","title":"未满足：漏洞披露信息","fields":[{"label":"检测项","value":"漏洞披露信息"},{"label":"加分数","value":"#tpl:+{p.s1}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出漏洞披露信息，+1 未得分","searchText":"漏洞披露"},{"when":"link=0","title":"未满足：联系链接","fields":[{"label":"检测项","value":"联系链接"},{"label":"加分数","value":"#tpl:+{p.s6}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出联系链接，+6 未得分","searchText":"联系链接"},{"when":"free_text=0","title":"未满足：自由文本说明","fields":[{"label":"检测项","value":"自由文本说明"},{"label":"加分数","value":"#tpl:+{p.s3}"},{"label":"判定","value":"未满足","level":"error"}],"reason":"未满足：SECURITY.md 中未检出自由文本安全说明，+3 未得分","searchText":"自由文本"}],"groups":[{"key":"check","label":"检测项","columns":[{"label":"检测项","key":"item","type":"text"},{"label":"结果","key":"result","type":"text"},{"label":"加分","key":"score","type":"number"}],"rows":[{"item":"漏洞披露信息","ok":"$disclosure","score":"#tpl:+{p.s1}"},{"item":"联系链接","ok":"$link","score":"#tpl:+{p.s6}"},{"item":"自由文本说明","ok":"$free_text","score":"#tpl:+{p.s3}"}],"cellOf":{"item":{"text":"$item"},"result":{"text":"#bool:$ok:满足:未满足","level":"#bool:$ok:success:error"},"score":{"text":"$score"}},"searchText":"#tpl:{item}"}],"rule":{"brief":"检查仓库是否提供安全政策文档 SECURITY.md（检查 .gitcode/、根目录、docs/ 等位置），内容包括漏洞披露说明、报告联系方式等。","formula":"仓库内存在 SECURITY.md = 10 分；仅所在社区层面存在 = 5 分；都不存在 = 0 分","conditions":[{"label":"仓库内","value":"检出 SECURITY.md 文件"},{"label":"社区层面","value":"仓库所在社区提供安全政策"}],"naCondition":"无，本指标恒有得分。","notes":[]}}',
1, 'ai-assisted', NOW());

-- VULNS
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('VULNS',
'{"params":{"priceCritical":"10","priceHigh":"5","priceMedium":"2","priceLow":"1"},"summary":[{"key":"total","label":"超期未关闭漏洞","value":"$overdue_count","level":"#ge:$overdue_count:1:error"},{"label":"致命","value":"$deduct_detail.critical","level":"#ge:$deduct_detail.critical:1:critical"},{"label":"高危","value":"$deduct_detail.high","level":"#ge:$deduct_detail.high:1:error"},{"label":"中危","value":"$deduct_detail.medium","level":"#ge:$deduct_detail.medium:1:warning"},{"label":"低危","value":"$deduct_detail.low"},{"key":"subCritical","hidden":true,"value":"#mul:$deduct_detail.critical,$p.priceCritical"},{"key":"subHigh","hidden":true,"value":"#mul:$deduct_detail.high,$p.priceHigh"},{"key":"subMedium","hidden":true,"value":"#mul:$deduct_detail.medium,$p.priceMedium"},{"key":"subLow","hidden":true,"value":"#mul:$deduct_detail.low,$p.priceLow"}],"failNote":"#tpl:评分：max(0, 10 − {deduct_detail.deduct_points}) = {score}　｜　扣分构成：致命 {deduct_detail.critical}×{p.priceCritical} + 高危 {deduct_detail.high}×{p.priceHigh} + 中危 {deduct_detail.medium}×{p.priceMedium} + 低危 {deduct_detail.low}×{p.priceLow} = {deduct_detail.deduct_points}　｜　漏洞的逐条清单在「全部扫描数据」里","failEmptyText":"全部满足：漏洞平台已覆盖本仓库，且无超期未关闭漏洞","dataNote":"本指标只统计「超期且未关闭」的漏洞：计划完成时间已过 且 状态非关闭态（closed / rejected 均视为关闭）。严重度为 None/空时按「低危」计入。明细按扣分降序排列。","failItems":[{"when":"deduct_detail.critical>=1","title":"#tpl:致命漏洞 {deduct_detail.critical} 个","fields":[{"label":"严重度","value":"致命","level":"critical"},{"label":"数量","value":"$deduct_detail.critical"},{"label":"单价扣分","value":"#tpl:-{p.priceCritical}"},{"label":"小计扣分","value":"#tpl:-{s.subCritical}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的致命漏洞 {deduct_detail.critical} 个，每个扣 {p.priceCritical} 分，小计扣 {s.subCritical} 分","deduct":"#tpl:-{s.subCritical}","searchText":"#tpl:致命 {deduct_detail.critical} 个 扣{p.priceCritical} 小计{s.subCritical}"},{"when":"deduct_detail.high>=1","title":"#tpl:高危漏洞 {deduct_detail.high} 个","fields":[{"label":"严重度","value":"高危","level":"error"},{"label":"数量","value":"$deduct_detail.high"},{"label":"单价扣分","value":"#tpl:-{p.priceHigh}"},{"label":"小计扣分","value":"#tpl:-{s.subHigh}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的高危漏洞 {deduct_detail.high} 个，每个扣 {p.priceHigh} 分，小计扣 {s.subHigh} 分","deduct":"#tpl:-{s.subHigh}","searchText":"#tpl:高危 {deduct_detail.high} 个 扣{p.priceHigh} 小计{s.subHigh}"},{"when":"deduct_detail.medium>=1","title":"#tpl:中危漏洞 {deduct_detail.medium} 个","fields":[{"label":"严重度","value":"中危","level":"warning"},{"label":"数量","value":"$deduct_detail.medium"},{"label":"单价扣分","value":"#tpl:-{p.priceMedium}"},{"label":"小计扣分","value":"#tpl:-{s.subMedium}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的中危漏洞 {deduct_detail.medium} 个，每个扣 {p.priceMedium} 分，小计扣 {s.subMedium} 分","deduct":"#tpl:-{s.subMedium}","searchText":"#tpl:中危 {deduct_detail.medium} 个 扣{p.priceMedium} 小计{s.subMedium}"},{"when":"deduct_detail.low>=1","title":"#tpl:低危漏洞 {deduct_detail.low} 个","fields":[{"label":"严重度","value":"低危"},{"label":"数量","value":"$deduct_detail.low"},{"label":"单价扣分","value":"#tpl:-{p.priceLow}"},{"label":"小计扣分","value":"#tpl:-{s.subLow}","level":"error"}],"reason":"#tpl:未满足：超期且未关闭的低危漏洞 {deduct_detail.low} 个，每个扣 {p.priceLow} 分，小计扣 {s.subLow} 分","deduct":"#tpl:-{s.subLow}","searchText":"#tpl:低危 {deduct_detail.low} 个 扣{p.priceLow} 小计{s.subLow}"}],"groups":[{"key":"vuln","label":"超期未关闭漏洞","columns":[{"label":"issue","key":"issue","type":"text"},{"label":"CVE 编号","key":"cve","type":"text"},{"label":"严重度","key":"sev","type":"text"},{"label":"计划完成时间","key":"plan","type":"text"},{"label":"状态","key":"status","type":"text"},{"label":"扣分","key":"deduct","type":"number"}],"rowsFrom":"$vuln_detail","cellOf":{"issue":{"text":"$issue_id","href":"#href:https://gitcode.com/{repoPath}/issues/{issue_id}"},"cve":{"text":"$cve_num"},"sev":{"text":"$severity","level":"#map:$severity:致命:critical,Critical:critical,critical:critical,高危:error,High:error,high:error,中危:warning,Medium:warning,medium:warning,*:"},"plan":{"text":"$plan_closed_time"},"status":{"text":"$status"},"deduct":{"text":"#map:$severity:critical:-10,Critical:-10,致命:-10,high:-5,High:-5,高危:-5,medium:-2,Medium:-2,中危:-2,low:-1,Low:-1,低危:-1,None:-1,*:-1","level":"#map:$severity:critical:critical,Critical:critical,致命:critical,high:error,High:error,高危:error,*:"}},"rowLevel":"#map:$severity:critical:critical,Critical:critical,致命:critical,high:error,High:error,高危:error,*:","searchText":"#tpl:{issue_id} {cve_num} {severity} {plan_closed_time} {status}"}],"rule":{"brief":"检查漏洞管理平台中本仓库已超期且未关闭的漏洞，按严重度扣分。已关闭、已拒绝的漏洞不计入。","formula":"得分 = 10 − (致命×10 + 高危×5 + 中危×2 + 低危×1)，最低 0 分","conditions":[{"label":"致命","value":"每个扣 10 分"},{"label":"高危","value":"每个扣 5 分"},{"label":"中危","value":"每个扣 2 分"},{"label":"低危","value":"每个扣 1 分（严重度未标注的按低危计）"}],"naCondition":"漏洞平台未跟踪本仓库时，本指标不参评（不计入总分，不是 0 分）。","notes":["有跟踪且无超期漏洞 = 满分 10 分","超期判定 = 计划修复时间已过且仍未关闭"]}}',
1, 'ai-assisted', NOW());

-- MAINTAINED
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('MAINTAINED',
'{"params":{"threshold":"13"},"summary":[{"key":"commit","label":"近 90 天 commit","value":"$commit_cnt_90d"},{"key":"issue","label":"近 90 天 issue","value":"$issue_cnt_90d"},{"key":"total","hidden":true,"value":"#add:$commit_cnt_90d,$issue_cnt_90d"},{"key":"gap","hidden":true,"value":"#sub:$p.threshold,$s.total"},{"key":"deduct","hidden":true,"value":"#sub:10,$score"},{"label":"合计 / 门槛","value":"#tpl:{s.total} / {p.threshold}","level":"#lt:$s.total:$p.threshold:error"},{"label":"仓库创建时间","value":"#ifnull:$repo_created:—"}],"failNote":"#tpl:评分：min(10, 10 × {s.total} / {p.threshold}) = {score}　｜　近 90 天 commit + issue 合计 {s.total}，门槛 {p.threshold}","failEmptyText":"全部满足：近 90 天 commit + issue 合计已达到门槛，无扣分","dataNote":"统计近 90 天的 commit 与 issue 活跃度，合计达到门槛即满分，未达门槛按比例计分（门槛可在 params.threshold 调整）。仓库已归档时本指标 NA。明细清单按时间倒序展示最近 20 条 commit 与 issue。","failItems":[{"when":"total<@p.threshold","title":"近 90 天活跃度未达门槛","fields":[{"label":"commit 数(90d)","value":"$commit_cnt_90d"},{"label":"issue 数(90d)","value":"$issue_cnt_90d"},{"label":"合计","value":"#tpl:{s.total}"},{"label":"门槛","value":"#tpl:{p.threshold}"},{"label":"差额","value":"#tpl:-{s.gap}","level":"error"}],"reason":"#tpl:未满足：近 90 天 commit + issue 合计 {s.total}，低于门槛 {p.threshold}，还差 {s.gap} 条","formula":"#tpl:score = min(10, 10 × {s.total} / {p.threshold}) = {score}","deduct":"#tpl:-{s.deduct}","searchText":"活跃度 门槛 commit issue"}],"groups":[{"key":"commits","label":"近 90 天 commit（最近 20 条）","columns":[{"label":"时间","key":"time","type":"text"},{"label":"作者","key":"author","type":"text"},{"label":"提交说明","key":"title","type":"text"},{"label":"链接","key":"link","type":"text"}],"rowsFrom":"$commit_rows","cellOf":{"time":{"text":"$commit_time"},"author":{"text":"#tpl:{author_name}（{author_username}）"},"title":{"text":"$commit_title"},"link":{"text":"查看","href":"#href:https://gitcode.com/{repoPath}/commit/{commit_hash}"}},"searchText":"#tpl:{author_name} {commit_title}"},{"key":"issues","label":"近 90 天 issue（最近 20 条）","columns":[{"label":"编号","key":"num","type":"text"},{"label":"状态","key":"state","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"},{"label":"创建时间","key":"time","type":"text"}],"rowsFrom":"$issue_rows","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"state":{"text":"#map:$state:open:开启,closed:已关闭,*:其他","level":"#map:$state:open:warning,closed:success,*:"},"title":{"text":"$title"},"creator":{"text":"$creator"},"time":{"text":"$created_at"}},"searchText":"#tpl:{title} {creator}"}],"emptyHint":"近 90 天无 commit / issue 活跃记录","rule":{"brief":"检查仓库近 90 天的维护活跃度 = 默认分支 commit 数 + 新建 issue 数。","formula":"得分 = 10 × (commit 数 + issue 数) / 13，上限 10 分（近 90 天合计 13 个即满分）","conditions":[{"label":"commit","value":"默认分支近 90 天提交数"},{"label":"issue","value":"近 90 天新建 issue 数"}],"naCondition":"仓库已归档、或创建时间不足 90 天（尚在孵化期）时，本指标不参评（不计入总分，不是 0 分）。","notes":[]}}',
1, 'ai-assisted', NOW());

-- CONTRIBUTORS
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('CONTRIBUTORS',
'{"params":{"minOrgs":"3"},"summary":[{"label":"作者数（去重）","value":"$author_count"},{"label":"组织数","value":"$n_orgs"},{"key":"n","label":"达标组织数 N","value":"#count:$qualified_orgs","level":"#lt:$s.n:$p.minOrgs:error"},{"label":"达标门槛","value":"#tpl:N ≥ {p.minOrgs}"}],"failNote":"#tpl:评分：min(10, 10 × 达标组织数 {s.n} / {p.minOrgs}) = {score}　｜　达标组织 = 该组织内存在至少 1 名作者近 30 次 PR 数达标　｜　因 min(10,…) 封顶，卡片不显示逐条扣分","failEmptyText":"全部满足：达标组织数已达门槛，贡献者多样性足够","dataNote":"贡献者口径为「近 30 次已合入 PR 的作者」（非全量贡献者）。⚠ 一个作者可归属多个组织，会同时计入其所有组织，故各组织作者数之和可能大于去重后的作者总数。组织内逐作者明细暂未采集。","failItems":[{"when":"n<@p.minOrgs","title":"达标组织数未达门槛","fields":[{"label":"作者数（去重）","value":"$author_count"},{"label":"组织数","value":"$n_orgs"},{"label":"达标组织数 N","value":"#tpl:{s.n}","level":"error"},{"label":"达标门槛","value":"#tpl:N ≥ {p.minOrgs}"}],"reason":"#tpl:未满足：达标组织数 {s.n}，低于门槛 {p.minOrgs}","searchText":"组织 多样性"}],"groups":[{"key":"org","label":"达标组织","columns":[{"label":"组织","key":"org","type":"text"}],"rowsFrom":"$qualified_orgs","cellOf":{"org":{"text":"$this"}},"searchText":"$this"}],"emptyHint":"组织内逐作者明细暂未采集，当前仅展示达标组织清单","rule":{"brief":"检查最近 30 次已合入 PR 的作者（剔除机器人）来自多少个不同组织，且这些组织中是否有活跃作者（近 30 次 PR 中个人贡献 ≥ 5 个）。","formula":"得分 = 10 × N / 3，上限 10 分（N = 存在至少 1 名活跃作者的组织个数，3 个即满分）","conditions":[{"label":"活跃作者","value":"近 30 次已合入 PR 中该作者贡献 ≥ 5 个"},{"label":"N 值","value":"存在至少 1 名活跃作者的组织个数"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"近 30 次已合入 PR 为 0 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]}}',
1, 'ai-assisted', NOW());

-- CODE_REVIEW
INSERT INTO dm_rd_efc_security_metric_detail_conf (metric_code, conf_json, enabled, updated_by, updated_at)
VALUES ('CODE_REVIEW',
'{"summary":[{"key":"total","label":"纳入统计 PR","value":"$pr_total_count"},{"key":"reviewed","label":"已评审","value":"$pr_reviewed_count","level":"#gt:$pr_reviewed_count:0:success"},{"key":"unreviewed","label":"未评审","value":"#sub:$pr_total_count,$pr_reviewed_count","level":"#lt:$pr_reviewed_count:$pr_total_count:error"},{"key":"rate","hidden":true,"value":"#pct:$pr_reviewed_count,$pr_total_count"},{"key":"deduct","hidden":true,"value":"#sub:10,$score"}],"failNote":"#tpl:评分：已评审 {pr_reviewed_count} / 纳入统计 {pr_total_count} × 10 = {score}　｜　每条未评审 PR 扣 10 / {pr_total_count}，合计扣 {s.deduct}　｜　评审率 {s.rate}%","failEmptyText":"全部满足：近 30 次已合入 PR 均已完成有效评审，无扣分","dataNote":"统计近 30 次已合入 PR（剔除机器人创建后纳入统计）。","failItems":{"from":"$pr_unreviewed_detail","card":{"title":"#tpl:PR #{number} 未通过评审","fields":[{"label":"PR","value":"#tpl:#{number}","href":"$url"},{"label":"标题","value":"#ifnull:$title:—"},{"label":"创建人","value":"#ifnull:$creator:—"},{"label":"合入时间","value":"$merged_at"},{"label":"评审结果","value":"未评审","level":"error"}],"reason":"#tpl:未满足：PR #{number} 已合入（{merged_at}）但未经过有效评审","searchText":"#tpl:{number} {title} {creator} 未评审 {merged_at}"}},"groups":[{"key":"pr","label":"未评审 PR 明细","columns":[{"label":"PR","key":"num","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"},{"label":"合入时间","key":"merged","type":"text"},{"label":"评审结果","key":"result","type":"text"}],"rowsFrom":"$pr_unreviewed_detail","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"title":{"text":"#ifnull:$title:—"},"creator":{"text":"#ifnull:$creator:—"},"merged":{"text":"$merged_at"},"result":{"text":"未评审","level":"error"}},"rowLevel":"error","searchText":"#tpl:{number} {title} {creator} {merged_at} 未评审"},{"key":"pr_all","label":"全部扫描 PR","columns":[{"label":"PR","key":"num","type":"text"},{"label":"标题","key":"title","type":"text"},{"label":"创建人","key":"creator","type":"text"}],"rowsFrom":"$pr_ci_detail","cellOf":{"num":{"text":"#tpl:#{number}","href":"$url"},"title":{"text":"#ifnull:$title:—"},"creator":{"text":"#ifnull:$creator:—"}},"searchText":"#tpl:{number} {title} {creator}"}],"rule":{"brief":"检查最近 30 次已合入 PR 中，每个 PR 是否存在有效评审：有「非机器人、非 PR 创建人」通过 /lgtm 或 /approve 命令给出认可。","formula":"得分 = 已评审 PR 数 / PR 总数 × 10","conditions":[{"label":"已评审","value":"存在非机器人、非创建人的 /lgtm 或 /approve 评论"},{"label":"PR 口径","value":"最近 30 次已合入 PR，剔除机器人创建的 PR"}],"naCondition":"剔除机器人创建的 PR 后数量为 0 时，本指标不参评（不计入总分，不是 0 分）。","notes":[]}}',
1, 'ai-assisted', NOW());
